@* A single Kanban column displaying its tasks and an add-task form *@

<div class="kanban-column">
    <div class="column-header">
        <h5>@Title <span class="badge bg-secondary">@Tasks.Count</span></h5>
    </div>

    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      CanMoveLeft="CanMoveLeft"
                      CanMoveRight="CanMoveRight"
                      IsMoving="movingTaskId == task.Id"
                      OnMoveLeft="() => HandleMove(task.Id, Direction.Left)"
                      OnMoveRight="() => HandleMove(task.Id, Direction.Right)" />
        }
    </div>

    <div class="column-footer">
        @if (showAddForm)
        {
            <AddTaskForm ColumnStatus="@Status"
                         TaskService="TaskService"
                         OnTaskCreated="HandleTaskCreated"
                         OnCancel="() => showAddForm = false" />
        }
        else
        {
            <button class="btn btn-sm btn-outline-primary w-100" @onclick="() => showAddForm = true">
                + Add Task
            </button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public string Title { get; set; } = "";

    [Parameter, EditorRequired]
    public string Status { get; set; } = "";

    [Parameter, EditorRequired]
    public List<TaskItem> Tasks { get; set; } = new();

    [Parameter]
    public bool CanMoveLeft { get; set; }

    [Parameter]
    public bool CanMoveRight { get; set; }

    /// <summary>Called when a task should be moved. Passes (taskId, direction).</summary>
    [Parameter, EditorRequired]
    public EventCallback<(int TaskId, Direction Dir)> OnMoveTask { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<TaskItem> OnTaskCreated { get; set; }

    [Parameter, EditorRequired]
    public ITaskService TaskService { get; set; } = default!;

    private bool showAddForm;
    private int? movingTaskId;

    private async Task HandleMove(int taskId, Direction dir)
    {
        movingTaskId = taskId;
        try
        {
            await OnMoveTask.InvokeAsync((taskId, dir));
        }
        finally
        {
            movingTaskId = null;
        }
    }

    private async Task HandleTaskCreated(TaskItem task)
    {
        showAddForm = false;
        await OnTaskCreated.InvokeAsync(task);
    }

    public enum Direction { Left, Right }
}

