+            errorMessage = ex.Message;
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private async Task HandleMoveTask((int TaskId, KanbanColumn.Direction Dir) move)
+    {
+        var task = allTasks.FirstOrDefault(t => t.Id == move.TaskId);
+        if (task is null) return;
+
+        var currentIndex = Array.IndexOf(ColumnOrder, task.Status);
+        var newIndex = move.Dir == KanbanColumn.Direction.Left ? currentIndex - 1 : currentIndex + 1;
+
+        if (newIndex < 0 || newIndex >= ColumnOrder.Length) return;
+
+        var newStatus = ColumnOrder[newIndex];
+
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
+            // Replace the task in our local list with the updated status
+            var index = allTasks.FindIndex(t => t.Id == task.Id);
+            allTasks[index] = task with { Status = newStatus };
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to move task: {ex.Message}";
+        }
+    }
+
+    private Task HandleTaskCreated(TaskItem task)
+    {
+        allTasks.Add(task);
+        return Task.CompletedTask;
+    }
+}
+

